INSERT INTO vi_business_base (company_id, code, name, kind, capital_basis, sort, boundary) VALUES ((SELECT id FROM vi_company_base WHERE code = '01698.HK'), 'B1', '在线音乐与音频娱乐平台', '经营', '企业', 1, 'QQ 音乐、酷狗、酷我、全民 K 歌、懒人听书等：会员订阅、非订阅音乐（广告、演出、周边、艺人经纪）、社交娱乐（直播打赏）三条收入线共用用户、曲库与团队。') ON CONFLICT (company_id, code) DO UPDATE SET name = EXCLUDED.name, kind = EXCLUDED.kind, capital_basis = EXCLUDED.capital_basis, sort = EXCLUDED.sort, boundary = EXCLUDED.boundary;
