INSERT INTO vi_judgment_base (company_id, code, title, status, judgment, transmission, parameter, change_threshold) VALUES ((SELECT id FROM vi_company_base WHERE code = '01698.HK'), 'J-IC', '期初投入资本（统一估值引擎）', '已形成建议', '2026-06-30 股东权益 782.7 亿元，减去资产负债桥 C1—C9 的账面净额 446.7 亿元（现金、负债、对外投资、经营所需现金、少数股东在非经营资产中的份额），经营投入资本 336.0 亿元（主要是收购形成的商誉约 298 亿元）。三条收入线共用这些资本，不拆分；之后资本占用率不变。', '投入资本是资产价值和 ROIC 的分母；收入增长按资本占用率占用新资本。', '估值假设·期初投入资本、资本占用率', '发生大额并购，或资本占用率明显变化。') ON CONFLICT (company_id, code) DO UPDATE SET title = EXCLUDED.title, status = EXCLUDED.status, judgment = EXCLUDED.judgment, transmission = EXCLUDED.transmission, parameter = EXCLUDED.parameter, change_threshold = EXCLUDED.change_threshold;
INSERT INTO vi_judgment_base (company_id, code, title, status, judgment, transmission, parameter, change_threshold) VALUES ((SELECT id FROM vi_company_base WHERE code = '01698.HK'), 'J-VE', '三条收入线、一块业务（统一估值引擎）', '已形成建议', '会员订阅、非订阅音乐、社交娱乐共用用户、曲库和团队，费用无法真实拆分，公司也只披露合计毛利率，所以按一块业务估值：收入分三条线各自预测，成本按利润表科目占全部收入的比例。2026、2028 年收入取财务预测，2027 年取各情景分部收入，2029 年起会员与非订阅按情景永续增长率、社交娱乐每年收缩 5%—10%；成本率 2029 年起保持 2028 年水平。', '收入线合计−营业成本−销售费用−管理费用＝经营利润。', '估值假设·收入线与成本线（2026—2035）', '公司披露分业务毛利，或成本结构（版权成本、分成比例）有持续变化。') ON CONFLICT (company_id, code) DO UPDATE SET title = EXCLUDED.title, status = EXCLUDED.status, judgment = EXCLUDED.judgment, transmission = EXCLUDED.transmission, parameter = EXCLUDED.parameter, change_threshold = EXCLUDED.change_threshold;
INSERT INTO vi_judgment_base (company_id, code, title, status, judgment, transmission, parameter, change_threshold) VALUES ((SELECT id FROM vi_company_base WHERE code = '01698.HK'), 'J-PROB', '情景概率 25% / 50% / 25%（待确认）', '已形成建议', '旧模型没有情景概率；先按悲观 25%、基准 50%、乐观 25% 给出概率加权价值。', '只影响概率加权每股价值。', '情景·情景概率', '有证据表明某一情景的可能性明显更高或更低。') ON CONFLICT (company_id, code) DO UPDATE SET title = EXCLUDED.title, status = EXCLUDED.status, judgment = EXCLUDED.judgment, transmission = EXCLUDED.transmission, parameter = EXCLUDED.parameter, change_threshold = EXCLUDED.change_threshold;
